//! Bulk import of SRD 5.1 monsters and spells from the 5e-database JSON
//! (`5e-SRD-Monsters.json`, `5e-SRD-Spells.json`, github.com/5e-bits/5e-database).
//! The SRD 5.1 is CC-BY-4.0; generated files carry the attribution.
//!
//! Plain weapon attacks, multiattack, saves, skills, damage traits and senses
//! are mapped to engine fields. Everything the engine cannot run (breath
//! weapons, legendary actions, auras, most spells) is kept as `manual` text
//! so the DM still has the full rule at the table.

use anyhow::{Context, Result};
use serde_json::{json, Map, Value};
use std::collections::BTreeSet;

pub const ATTRIBUTION: &str = "# Generated by `combat-sim content import-srd` from the System Reference Document 5.1\n# by Wizards of the Coast LLC, licensed CC-BY-4.0 (https://creativecommons.org/licenses/by/4.0/),\n# via the 5e-database JSON (github.com/5e-bits/5e-database). Regenerate rather than hand-edit;\n# hand-tuned versions with the same id live in monsters/ and spells.yaml and win.\n";

const ABILITIES: [(&str, &str); 6] = [
    ("strength", "str"),
    ("dexterity", "dex"),
    ("constitution", "con"),
    ("intelligence", "int"),
    ("wisdom", "wis"),
    ("charisma", "cha"),
];

fn feet(v: &Value) -> Option<i32> {
    let s = v.as_str()?;
    s.split_whitespace().next()?.parse().ok()
}

fn modifier(score: i64) -> i64 {
    (score - 10).div_euclid(2)
}

pub fn slug(s: &str) -> String {
    let mut out = String::new();
    for c in s.to_lowercase().chars() {
        if c.is_ascii_alphanumeric() {
            out.push(c);
        } else if !out.ends_with('-') && !out.is_empty() && c != '\'' {
            out.push('-');
        }
    }
    out.trim_end_matches('-').to_string()
}

fn damage_parts(v: &Value) -> Vec<Value> {
    let mut out = Vec::new();
    for d in v.as_array().into_iter().flatten() {
        // `choose` blocks (one of two forms) keep only the first option.
        let d = match d
            .get("from")
            .and_then(|f| f.get("options"))
            .and_then(|o| o.get(0))
        {
            Some(first) => first,
            None => d,
        };
        let (Some(dice), Some(ty)) = (
            d.get("damage_dice").and_then(Value::as_str),
            d.pointer("/damage_type/index").and_then(Value::as_str),
        ) else {
            continue;
        };
        out.push(json!({"dice": dice.replace(' ', ""), "type": ty}));
    }
    out
}

/// "Melee Weapon Attack: +4 to hit, reach 5 ft." / "Ranged ...: range 80/320 ft."
fn attack_shape(desc: &str) -> (&'static str, Option<i32>, Option<[i32; 2]>) {
    let low = desc.to_lowercase();
    let kind = if low.starts_with("melee or ranged") {
        "melee_or_ranged"
    } else if low.starts_with("ranged") {
        "ranged"
    } else {
        "melee"
    };
    let num_after = |key: &str| -> Option<&str> {
        let i = low.find(key)? + key.len();
        Some(low[i..].split_whitespace().next().unwrap_or(""))
    };
    let reach = num_after("reach ").and_then(|n| n.parse().ok());
    let range = num_after("range ").and_then(|n| {
        let mut it = n.split('/').map(|x| {
            x.trim_end_matches(|c: char| !c.is_ascii_digit())
                .parse::<i32>()
        });
        match (it.next(), it.next()) {
            (Some(Ok(a)), Some(Ok(b))) => Some([a, b]),
            (Some(Ok(a)), None) => Some([a, a]),
            _ => None,
        }
    });
    (kind, reach, range)
}

fn ai_template(m: &Value) -> &'static str {
    let int = m.get("intelligence").and_then(Value::as_i64).unwrap_or(10);
    let ty = m.get("type").and_then(Value::as_str).unwrap_or("");
    if int <= 3 || ty == "construct" || ty == "ooze" {
        "mindless"
    } else {
        "brute"
    }
}

fn condition_names(v: &Value) -> Vec<Value> {
    v.as_array()
        .into_iter()
        .flatten()
        .filter_map(|c| c.get("index").and_then(Value::as_str))
        .map(|s| json!(s))
        .collect()
}

/// Damage traits: plain types become engine fields; conditional ones
/// ("bludgeoning ... from nonmagical attacks") go to the notes.
fn damage_traits(v: &Value, notes: &mut Vec<String>, label: &str) -> Vec<Value> {
    let mut out = Vec::new();
    for s in v.as_array().into_iter().flatten().filter_map(Value::as_str) {
        let w = s.trim().to_lowercase();
        if w.split_whitespace().count() == 1 {
            out.push(json!(w));
        } else {
            notes.push(format!("{label}: {s}"));
        }
    }
    out
}

/// Human-readable statblock kept next to the structured fields so the DM can
/// read the full action text without the PDF.
fn statblock(m: &Value) -> String {
    let mut out = String::new();
    let name = m.get("name").and_then(Value::as_str).unwrap_or("");
    let size = m.get("size").and_then(Value::as_str).unwrap_or("");
    let ty = m.get("type").and_then(Value::as_str).unwrap_or("");
    let alignment = m.get("alignment").and_then(Value::as_str).unwrap_or("");
    out.push_str(name);
    out.push_str(&format!("\n{size} {ty}, {alignment}"));
    if let Some(ac) = m.pointer("/armor_class/0/value").and_then(Value::as_i64) {
        let kind = m
            .pointer("/armor_class/0/type")
            .and_then(Value::as_str)
            .filter(|k| !k.is_empty())
            .map(|k| format!(" ({k})"))
            .unwrap_or_default();
        out.push_str(&format!("\nAC {ac}{kind}"));
    }
    if let Some(hp) = m.get("hit_points").and_then(Value::as_i64) {
        let roll = m
            .get("hit_points_roll")
            .and_then(Value::as_str)
            .unwrap_or("");
        out.push_str(&format!("\nHP {hp} ({roll})"));
    }
    if let Some(speed) = m.get("speed").and_then(Value::as_object) {
        let parts: Vec<String> = speed
            .iter()
            .map(|(k, v)| {
                let v = v
                    .as_str()
                    .map(str::to_string)
                    .unwrap_or_else(|| v.to_string());
                format!("{} {v}", k.replace('_', " "))
            })
            .collect();
        out.push_str(&format!("\nSpeed {}", parts.join(", ")));
    }
    let abilities: Vec<String> = ABILITIES
        .iter()
        .map(|(long, short)| {
            let score = m.get(*long).and_then(Value::as_i64).unwrap_or(10);
            format!("{} {score} ({:+})", short.to_uppercase(), modifier(score))
        })
        .collect();
    out.push_str(&format!("\n{}", abilities.join(", ")));
    for (key, label) in [
        ("skills", "Skills"),
        ("senses", "Senses"),
        ("languages", "Languages"),
    ] {
        match m.get(key) {
            Some(Value::String(s)) if !s.is_empty() => out.push_str(&format!("\n{label} {s}")),
            Some(Value::Object(o)) if !o.is_empty() => {
                let parts: Vec<String> = o
                    .iter()
                    .map(|(k, v)| {
                        format!(
                            "{} {}",
                            k.replace('_', " "),
                            v.as_str()
                                .map(str::to_string)
                                .unwrap_or_else(|| v.to_string())
                        )
                    })
                    .collect();
                out.push_str(&format!("\n{label} {}", parts.join(", ")));
            }
            _ => {}
        }
    }
    if let Some(cr) = m.get("challenge_rating").and_then(Value::as_f64) {
        let xp = m.get("xp").and_then(Value::as_i64).unwrap_or(0);
        out.push_str(&format!("\nCR {cr} (XP {xp})"));
    }
    for (key, heading) in [
        ("special_abilities", "Traits"),
        ("actions", "Actions"),
        ("bonus_actions", "Bonus Actions"),
        ("reactions", "Reactions"),
        ("legendary_actions", "Legendary Actions"),
    ] {
        let items = m.get(key).and_then(Value::as_array).into_iter().flatten();
        let mut block = String::new();
        for item in items {
            let n = item.get("name").and_then(Value::as_str).unwrap_or("");
            let d = item.get("desc").and_then(Value::as_str).unwrap_or("");
            if n.is_empty() && d.is_empty() {
                continue;
            }
            block.push_str(&format!("\n{n}. {d}"));
        }
        if !block.is_empty() {
            out.push_str(&format!("\n\n{heading}{block}"));
        }
    }
    out.trim().to_string()
}

pub fn monster(m: &Value, label: &str) -> Option<Value> {
    let id = m.get("index")?.as_str()?.to_string();
    let name = m.get("name")?.as_str()?;
    let mut c = Map::new();
    let mut notes: Vec<String> = Vec::new();
    c.insert("id".into(), json!(id));
    c.insert("name".into(), json!(name));
    c.insert("kind".into(), json!("monster"));
    c.insert(
        "size".into(),
        json!(m.get("size")?.as_str()?.to_lowercase()),
    );
    c.insert(
        "creature_type".into(),
        json!(m.get("type")?.as_str()?.to_lowercase()),
    );
    let ac = m.pointer("/armor_class/0/value").and_then(Value::as_i64)?;
    c.insert("ac".into(), json!(ac));
    c.insert("hp".into(), json!(m.get("hit_points")?.as_i64()?));
    let mut speed = Map::new();
    for (k, v) in m
        .get("speed")
        .and_then(Value::as_object)
        .into_iter()
        .flatten()
    {
        if k == "hover" {
            if v.as_bool() == Some(true) {
                speed.insert("hover".into(), json!(true));
            }
            continue;
        }
        if let Some(f) = feet(v) {
            if ["walk", "climb", "fly", "swim", "burrow"].contains(&k.as_str()) {
                speed.insert(k.clone(), json!(f));
            } else {
                notes.push(format!("{k} speed {f} ft."));
            }
        }
    }
    speed.entry("walk").or_insert(json!(0));
    c.insert("speed".into(), Value::Object(speed));
    let dex = m.get("dexterity").and_then(Value::as_i64).unwrap_or(10);
    c.insert("init_bonus".into(), json!(modifier(dex)));
    let prof = m
        .get("proficiency_bonus")
        .and_then(Value::as_i64)
        .unwrap_or(2);
    c.insert("prof".into(), json!(prof));
    let mut ab = Map::new();
    for (long, short) in ABILITIES {
        ab.insert(
            short.into(),
            json!(m.get(long).and_then(Value::as_i64).unwrap_or(10)),
        );
    }
    c.insert("abilities".into(), Value::Object(ab));
    let (mut saves, mut skills) = (Map::new(), Map::new());
    for p in m
        .get("proficiencies")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
    {
        let (Some(idx), Some(v)) = (
            p.pointer("/proficiency/index").and_then(Value::as_str),
            p.get("value").and_then(Value::as_i64),
        ) else {
            continue;
        };
        if let Some(a) = idx.strip_prefix("saving-throw-") {
            saves.insert(a.into(), json!(v));
        } else if let Some(s) = idx.strip_prefix("skill-") {
            skills.insert(s.replace('-', "_"), json!(v));
        }
    }
    if !saves.is_empty() {
        c.insert("saves".into(), Value::Object(saves));
    }
    if !skills.is_empty() {
        c.insert("skills".into(), Value::Object(skills));
    }
    for (src, dst, label) in [
        ("damage_resistances", "resistances", "Resistances"),
        ("damage_immunities", "immunities", "Immunities"),
        (
            "damage_vulnerabilities",
            "vulnerabilities",
            "Vulnerabilities",
        ),
    ] {
        let v = damage_traits(m.get(src).unwrap_or(&Value::Null), &mut notes, label);
        if !v.is_empty() {
            c.insert(dst.into(), Value::Array(v));
        }
    }
    let ci = condition_names(m.get("condition_immunities").unwrap_or(&Value::Null));
    if !ci.is_empty() {
        c.insert("condition_immunities".into(), Value::Array(ci));
    }
    let mut senses: Vec<String> = Vec::new();
    for (k, v) in m
        .get("senses")
        .and_then(Value::as_object)
        .into_iter()
        .flatten()
    {
        let label = k.replace('_', " ");
        let label = label[..1].to_uppercase() + &label[1..];
        match v {
            Value::String(s) => senses.push(format!("{label} {s}")),
            other => senses.push(format!("{label} {other}")),
        }
    }
    if !senses.is_empty() {
        c.insert("senses".into(), json!(senses.join("; ")));
    }
    // Actions.
    let mut attacks = Vec::new();
    let mut features = Vec::new();
    let mut attack_ids: Vec<(String, String)> = Vec::new(); // (name lower, id)
    let mut multi: Option<&Value> = None;
    for a in m
        .get("actions")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
    {
        let an = a.get("name").and_then(Value::as_str).unwrap_or("Action");
        let desc = a.get("desc").and_then(Value::as_str).unwrap_or("");
        if an == "Multiattack" {
            multi = Some(a);
            features.push(feature(&id, an, "action", desc));
            continue;
        }
        let dmg = damage_parts(a.get("damage").unwrap_or(&Value::Null));
        if let (Some(hit), false, true) = (
            a.get("attack_bonus").and_then(Value::as_i64),
            dmg.is_empty(),
            a.get("dc").is_none(),
        ) {
            let (kind, reach, range) = attack_shape(desc);
            let aid = slug(an);
            let mut at = Map::new();
            at.insert("id".into(), json!(aid));
            at.insert("name".into(), json!(an));
            at.insert("kind".into(), json!(kind));
            at.insert("to_hit".into(), json!(hit));
            at.insert("damage".into(), Value::Array(dmg));
            if let Some(r) = reach {
                at.insert("reach".into(), json!(r));
            }
            if let Some(r) = range {
                at.insert("range".into(), json!(r));
            }
            // Rider text after the damage ("... and the target is grappled").
            if let Some(i) = desc.find(" damage") {
                let rest = desc[i + 7..].trim_start_matches(['.', ',']).trim();
                if rest.len() > 3 {
                    at.insert("manual".into(), json!(rest));
                }
            }
            attack_ids.push((an.to_lowercase(), aid));
            attacks.push(Value::Object(at));
        } else {
            features.push(feature(&id, an, "action", desc));
        }
    }
    if let Some(ma) = multi {
        let mut seq = Vec::new();
        let mut complete = true;
        for x in ma
            .get("actions")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
        {
            let n = x
                .get("action_name")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_lowercase();
            let count = x
                .get("count")
                .and_then(|v| {
                    v.as_i64()
                        .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
                })
                .unwrap_or(1);
            match attack_ids.iter().find(|(nm, _)| *nm == n) {
                Some((_, aid)) => (0..count).for_each(|_| seq.push(json!(aid))),
                None => complete = false,
            }
        }
        if !seq.is_empty()
            && complete
            && ma.get("multiattack_type").and_then(Value::as_str) != Some("action_options")
        {
            c.insert("multiattack".into(), Value::Array(seq));
        }
    }
    for (key, act) in [
        ("special_abilities", "passive"),
        ("reactions", "reaction"),
        ("legendary_actions", "free"),
    ] {
        for a in m.get(key).and_then(Value::as_array).into_iter().flatten() {
            let an = a.get("name").and_then(Value::as_str).unwrap_or("Feature");
            let desc = a.get("desc").and_then(Value::as_str).unwrap_or("");
            let an = if key == "legendary_actions" {
                format!("Legendary: {an}")
            } else {
                an.to_string()
            };
            features.push(feature(&id, &an, act, desc));
        }
    }
    if m.get("legendary_actions")
        .and_then(Value::as_array)
        .is_some_and(|v| !v.is_empty())
    {
        notes.push(
            "legendary actions are manual (3 per round, at the end of other creatures' turns)"
                .into(),
        );
    }
    if !attacks.is_empty() {
        c.insert("attacks".into(), Value::Array(attacks));
    }
    if !features.is_empty() {
        c.insert("features".into(), Value::Array(dedupe_ids(features)));
    }
    c.insert("ai".into(), json!({"template": ai_template(m)}));
    let cr = m
        .get("challenge_rating")
        .and_then(Value::as_f64)
        .unwrap_or(0.0);
    let cr_s = match cr {
        0.125 => "1/8".to_string(),
        0.25 => "1/4".to_string(),
        0.5 => "1/2".to_string(),
        x => format!("{x}"),
    };
    let xp = m.get("xp").and_then(Value::as_i64).unwrap_or(0);
    let roll = m
        .get("hit_points_roll")
        .and_then(Value::as_str)
        .unwrap_or("");
    let mut note = format!(
        "{label} {name}, CR {cr_s} (XP {xp}), HP {} ({roll}).",
        c["hp"]
    );
    if !notes.is_empty() {
        note.push(' ');
        note.push_str(&notes.join("; "));
        note.push('.');
    }
    c.insert("notes".into(), json!(note));
    c.insert("manual".into(), json!(statblock(m)));
    c.insert(
        "tags".into(),
        json!(["srd", format!("cr-{}", cr_s.replace('/', "-"))]),
    );
    Some(Value::Object(c))
}

fn feature(owner: &str, name: &str, activation: &str, desc: &str) -> Value {
    json!({
        "id": format!("{owner}-{}", slug(name)),
        "name": name,
        "activation": activation,
        "manual": desc,
    })
}

fn dedupe_ids(items: Vec<Value>) -> Vec<Value> {
    let mut seen = BTreeSet::new();
    items
        .into_iter()
        .map(|mut v| {
            let base = v["id"].as_str().unwrap_or("").to_string();
            let mut id = base.clone();
            let mut n = 2;
            while !seen.insert(id.clone()) {
                id = format!("{base}-{n}");
                n += 1;
            }
            v["id"] = json!(id);
            v
        })
        .collect()
}

fn spell_range(s: &Value) -> Option<i32> {
    let r = s.get("range")?.as_str()?.to_lowercase();
    if r == "touch" {
        return Some(5);
    }
    if r == "self" {
        return Some(0);
    }
    r.split_whitespace().next()?.parse().ok()
}

fn first_dice(map: Option<&Value>) -> Option<(String, String)> {
    let o = map?.as_object()?;
    let (k, v) = o
        .iter()
        .min_by_key(|(k, _)| k.parse::<i32>().unwrap_or(99))?;
    Some((k.clone(), v.as_str()?.replace(' ', "")))
}

/// Width of a line area in the SRD text ("5-foot-wide", "10 feet wide").
fn line_width(text: &str) -> Option<i32> {
    for marker in ["-foot-wide", "-feet-wide", " foot wide", " feet wide"] {
        let Some(index) = text.find(marker) else {
            continue;
        };
        let digits: String = text[..index]
            .chars()
            .rev()
            .take_while(char::is_ascii_digit)
            .collect::<String>()
            .chars()
            .rev()
            .collect();
        if let Ok(width) = digits.parse() {
            return Some(width);
        }
    }
    None
}

/// Maps upstream `area_of_effect` to the frozen #170 `AreaSpec`. `radius` is
/// the generic size (sphere radius, cone length, cube side, cylinder radius,
/// line length); `width_ft` only carries the line width. Wall-shaped upstream
/// lines are not a line area and stay unset.
fn spell_area(s: &Value) -> Option<Value> {
    let kind = s.pointer("/area_of_effect/type")?.as_str()?;
    let size = s.pointer("/area_of_effect/size")?.as_i64()?;
    let name = s.get("name").and_then(Value::as_str).unwrap_or("");
    let desc = text_blocks(s.get("desc").or_else(|| s.get("description"))).join(" ");
    let text = format!("{name} {desc}").to_lowercase();
    match kind {
        "sphere" | "cone" | "cube" | "cylinder" => Some(json!({"radius": size, "shape": kind})),
        "line" if !text.contains("wall") => {
            let mut area = json!({"radius": size, "shape": "line"});
            if let Some(width) = line_width(&text) {
                area["width_ft"] = json!(width);
            }
            Some(area)
        }
        _ => None,
    }
}

/// A text field that upstream writes either as a string (2024) or an array of
/// paragraphs (2014).
pub(crate) fn text_blocks(value: Option<&Value>) -> Vec<String> {
    match value {
        Some(Value::String(text)) => vec![text.clone()],
        Some(Value::Array(items)) => items
            .iter()
            .filter_map(Value::as_str)
            .map(str::to_string)
            .collect(),
        _ => Vec::new(),
    }
}

pub fn spell(s: &Value, label: &str) -> Option<Value> {
    let id = s.get("index")?.as_str()?;
    let name = s.get("name")?.as_str()?;
    let level = s.get("level")?.as_i64()?;
    let desc = text_blocks(s.get("desc").or_else(|| s.get("description")));
    if desc.is_empty() {
        return None;
    }
    let higher = text_blocks(s.get("higher_level"));
    let mut a = Map::new();
    let mut tags = vec![json!("spell"), json!("srd")];
    if level == 0 {
        tags.push(json!("cantrip"));
    }
    if s.get("ritual").and_then(Value::as_bool) == Some(true) {
        tags.push(json!("ritual"));
    }
    if let Some(school) = s.pointer("/school/index").and_then(Value::as_str) {
        tags.push(json!(school));
    }
    a.insert("id".into(), json!(id));
    a.insert("name".into(), json!(name));
    a.insert("tags".into(), Value::Array(tags));
    let ct = s
        .get("casting_time")
        .and_then(Value::as_str)
        .unwrap_or("1 action")
        .to_lowercase();
    let activation = if ct.contains("bonus") {
        "bonus"
    } else if ct.contains("reaction") {
        "reaction"
    } else {
        "action"
    };
    a.insert("activation".into(), json!(activation));
    if level > 0 {
        a.insert(
            "cost".into(),
            json!({"resource": format!("spell-slot-{level}"), "amount": 1}),
        );
        a.insert("slot_level".into(), json!(level));
    }
    let range = spell_range(s);
    if let Some(r) = range {
        a.insert("range".into(), json!(r));
    }
    let conc = s
        .get("concentration")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    if conc {
        a.insert("concentration".into(), json!(true));
    }
    let dmg = s.get("damage");
    let dtype = dmg
        .and_then(|d| d.pointer("/damage_type/index"))
        .and_then(Value::as_str);
    let dice = first_dice(dmg.and_then(|d| d.get("damage_at_slot_level")))
        .or_else(|| first_dice(dmg.and_then(|d| d.get("damage_at_character_level"))));
    let heal = first_dice(s.get("heal_at_slot_level"));
    let attack = s.get("attack_type").and_then(Value::as_str);
    let save = s.pointer("/dc/dc_type/index").and_then(Value::as_str);
    let success = s
        .pointer("/dc/dc_success")
        .and_then(Value::as_str)
        .unwrap_or("none");
    let area = spell_area(s);
    let mut effects = Vec::new();
    let mut role = "none";
    let mut target = json!({"type": "creature", "side": "enemy", "count": 1});
    let mut todo: Vec<String> = Vec::new();
    match (attack, save, dice.as_ref(), dtype, heal.as_ref()) {
        (Some(kind), _, Some((_, d)), Some(t), _) => {
            effects.push(json!({"attack": {"to_hit": "{spell_attack}", "kind": kind, "damage": [{"dice": d, "type": t}]}}));
            role = "damage";
        }
        (None, Some(ab), Some((_, d)), Some(t), _) => {
            let mut sv = json!({"ability": ab, "dc": "{spell_dc}", "on_fail": [{"damage": {"dice": d, "type": t}}]});
            if success == "half" {
                sv["half"] = json!(true);
            }
            effects.push(json!({"save": sv}));
            role = "damage";
        }
        (None, None, None, None, Some((_, h))) => {
            let h = h.replace("MOD", "{spell_mod}");
            effects.push(json!({"heal": {"dice": h}}));
            role = "heal";
            target = json!({"type": "creature", "side": "ally", "count": 1});
        }
        _ => {
            target = json!({"type": "self"});
        }
    }
    if effects.is_empty() || range == Some(0) && role == "none" {
        target = json!({"type": "self"});
    }
    a.insert("target".into(), target);
    if let Some(area) = area {
        a.insert("area".into(), area);
    }
    let mut text = desc.join("\n\n");
    if !higher.is_empty() {
        text.push_str("\n\nAt higher levels: ");
        text.push_str(&higher.join(" "));
    }
    if effects.is_empty() {
        effects.push(json!({"note": format!("{name} ({label}, manual): see `manual`.")}));
    } else if !higher.is_empty() || dice.as_ref().is_some_and(|(k, _)| k != "1" && level == 0) {
        todo.push("upcast / cantrip scaling not modelled (lowest level dice used)".into());
    }
    a.insert("effects".into(), Value::Array(effects));
    a.insert("ai".into(), json!({"role": role}));
    let comps = s
        .get("components")
        .and_then(Value::as_array)
        .map(|v| {
            v.iter()
                .filter_map(Value::as_str)
                .collect::<Vec<_>>()
                .join(", ")
        })
        .unwrap_or_default();
    let dur = s.get("duration").and_then(Value::as_str).unwrap_or("");
    a.insert(
        "manual".into(),
        json!(format!(
            "{ct}; {} ; {comps}; {dur}.\n\n{text}",
            s.get("range").and_then(Value::as_str).unwrap_or("")
        )),
    );
    a.insert("source".into(), json!(format!("{label} {name}")));
    if !todo.is_empty() {
        a.insert("todo".into(), json!(todo));
    }
    Some(Value::Object(a))
}

/// Ids already defined by hand-made files (they win over the bulk import).
pub fn existing_ids(dirs: &[std::path::PathBuf]) -> Result<BTreeSet<String>> {
    let mut ids = BTreeSet::new();
    for d in dirs {
        let mut files = Vec::new();
        walk(d, &mut files);
        for f in files {
            let text = std::fs::read_to_string(&f).with_context(|| f.display().to_string())?;
            for line in text.lines() {
                if let Some(rest) = line.trim_start().strip_prefix("- id:") {
                    ids.insert(rest.trim().trim_matches('"').to_string());
                }
            }
        }
    }
    Ok(ids)
}

fn walk(p: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
    if p.is_dir() {
        let mut es: Vec<_> = std::fs::read_dir(p)
            .into_iter()
            .flatten()
            .flatten()
            .map(|e| e.path())
            .collect();
        es.sort();
        for e in es {
            walk(&e, out);
        }
    } else if p.extension().is_some_and(|e| e == "yaml" || e == "yml") {
        out.push(p.to_path_buf());
    }
}

pub fn convert_monsters(v: &Value, skip: &BTreeSet<String>) -> (Value, usize) {
    let list: Vec<Value> = v
        .as_array()
        .into_iter()
        .flatten()
        .filter(|m| {
            m.get("index")
                .and_then(Value::as_str)
                .is_some_and(|i| !skip.contains(i))
        })
        .filter_map(|m| monster(m, "SRD 5.1"))
        .collect();
    let n = list.len();
    (json!({"creatures": list}), n)
}

pub fn convert_spells(v: &Value, skip: &BTreeSet<String>) -> (Value, usize) {
    let list: Vec<Value> = v
        .as_array()
        .into_iter()
        .flatten()
        .filter(|m| {
            m.get("index")
                .and_then(Value::as_str)
                .is_some_and(|i| !skip.contains(i))
        })
        .filter_map(|s| spell(s, "SRD 5.1"))
        .collect();
    let n = list.len();
    (json!({"abilities": list}), n)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn monster_json(speed: Value) -> Value {
        json!({
            "index": "test-monster",
            "name": "Test Monster",
            "size": "Medium",
            "type": "beast",
            "armor_class": [{"value": 12}],
            "hit_points": 10,
            "speed": speed,
            "strength": 10,
            "dexterity": 10,
            "constitution": 10,
            "intelligence": 10,
            "wisdom": 10,
            "charisma": 10,
            "challenge_rating": 1,
            "xp": 200
        })
    }

    #[test]
    fn monster_speed_structures_hover_and_burrow() {
        let value = monster(
            &monster_json(json!({
                "walk": "0 ft.",
                "fly": "50 ft.",
                "hover": true,
                "burrow": "20 ft."
            })),
            "SRD 5.1",
        )
        .expect("monster");
        assert_eq!(
            value["speed"],
            json!({"walk": 0, "fly": 50, "hover": true, "burrow": 20})
        );
        let notes = value["notes"].as_str().unwrap_or("");
        assert!(!notes.contains("can hover"), "{notes}");
        assert!(!notes.contains("burrow speed"), "{notes}");
    }

    #[test]
    fn spell_area_maps_shapes_and_line_width() {
        let sphere = json!({
            "index": "fireball", "name": "Fireball", "level": 3,
            "desc": ["A 20-foot-radius sphere."],
            "range": "150 feet", "casting_time": "1 action",
            "area_of_effect": {"type": "sphere", "size": 20}
        });
        assert_eq!(
            spell_area(&sphere),
            Some(json!({"radius": 20, "shape": "sphere"}))
        );

        let line = json!({
            "index": "lightning-bolt", "name": "Lightning Bolt", "level": 3,
            "desc": ["A stroke of lightning forming a line 100 feet long and 5 feet wide."],
            "area_of_effect": {"type": "line", "size": 100}
        });
        assert_eq!(
            spell_area(&line),
            Some(json!({"radius": 100, "shape": "line", "width_ft": 5}))
        );
    }

    #[test]
    fn spell_area_skips_wall_shaped_lines() {
        let wall = json!({
            "index": "wall-of-fire", "name": "Wall of Fire", "level": 4,
            "desc": ["You create a wall of fire on a solid surface."],
            "area_of_effect": {"type": "line", "size": 60}
        });
        assert_eq!(spell_area(&wall), None);
    }
}
